-- ORBIT initial schema (0001)
--
-- Conventions:
--   * UUIDv7 primary keys generated by the application (time-ordered).
--   * timestamptz in UTC; the application maintains updated_at.
--   * org_id on every tenant-owned row; queries must scope by it.
--   * Enumerations are text with CHECK constraints (migration-friendly, readable dumps).
--   * JSONB only for flexible configuration; relationships stay relational.

CREATE TABLE organizations (
    id          uuid PRIMARY KEY,
    slug        text NOT NULL UNIQUE,
    name        text NOT NULL,
    mode        text NOT NULL DEFAULT 'personal'
                CHECK (mode IN ('personal', 'enterprise')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    org_id        uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    email         text NOT NULL,
    display_name  text NOT NULL,
    role          text NOT NULL DEFAULT 'viewer'
                  CHECK (role IN ('owner', 'admin', 'operator', 'viewer')),
    status        text NOT NULL DEFAULT 'active'
                  CHECK (status IN ('active', 'invited', 'disabled')),
    oidc_issuer   text,
    oidc_subject  text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (org_id, email)
);

CREATE UNIQUE INDEX users_oidc_identity_idx
    ON users (oidc_issuer, oidc_subject)
    WHERE oidc_issuer IS NOT NULL AND oidc_subject IS NOT NULL;
CREATE INDEX users_org_idx ON users (org_id, created_at DESC);

CREATE TABLE api_tokens (
    id           uuid PRIMARY KEY,
    org_id       uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name         text NOT NULL,
    token_prefix text NOT NULL,
    token_hash   text NOT NULL UNIQUE,
    scopes       text[] NOT NULL DEFAULT '{}',
    expires_at   timestamptz,
    last_used_at timestamptz,
    revoked_at   timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX api_tokens_org_idx ON api_tokens (org_id, created_at DESC);

CREATE TABLE runtimes (
    id                    uuid PRIMARY KEY,
    org_id                uuid REFERENCES organizations(id) ON DELETE CASCADE,
    kind                  text NOT NULL,
    name                  text NOT NULL,
    description           text NOT NULL DEFAULT '',
    enabled               boolean NOT NULL DEFAULT true,
    implementation_status text NOT NULL DEFAULT 'planned'
                          CHECK (implementation_status IN ('available', 'scaffolded', 'planned')),
    capabilities          jsonb NOT NULL DEFAULT '{}'::jsonb,
    config                jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX runtimes_builtin_kind_idx ON runtimes (kind) WHERE org_id IS NULL;
CREATE UNIQUE INDEX runtimes_org_kind_idx ON runtimes (org_id, kind) WHERE org_id IS NOT NULL;

CREATE TABLE providers (
    id          uuid PRIMARY KEY,
    org_id      uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name        text NOT NULL,
    kind        text NOT NULL
                CHECK (kind IN ('openai_compatible', 'runtime_managed')),
    config      jsonb NOT NULL DEFAULT '{}'::jsonb,
    secret_ref  text,
    enabled     boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (org_id, name)
);
CREATE INDEX providers_org_idx ON providers (org_id, created_at DESC);

CREATE TABLE connectors (
    id            uuid PRIMARY KEY,
    org_id        uuid REFERENCES organizations(id) ON DELETE CASCADE,
    slug          text NOT NULL,
    name          text NOT NULL,
    version       text NOT NULL DEFAULT '0.1.0',
    description   text NOT NULL DEFAULT '',
    auth          jsonb NOT NULL DEFAULT '[]'::jsonb,
    capabilities  jsonb NOT NULL DEFAULT '[]'::jsonb,
    config_schema jsonb NOT NULL DEFAULT '{}'::jsonb,
    webhooks      boolean NOT NULL DEFAULT false,
    builtin       boolean NOT NULL DEFAULT true,
    docs_url      text,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX connectors_builtin_slug_idx ON connectors (slug) WHERE org_id IS NULL;
CREATE UNIQUE INDEX connectors_org_slug_idx ON connectors (org_id, slug) WHERE org_id IS NOT NULL;

CREATE TABLE connections (
    id             uuid PRIMARY KEY,
    org_id         uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    connector_id   uuid NOT NULL REFERENCES connectors(id) ON DELETE RESTRICT,
    name           text NOT NULL,
    status         text NOT NULL DEFAULT 'active'
                   CHECK (status IN ('active', 'expired', 'revoked', 'error')),
    credential_ref text,
    config         jsonb NOT NULL DEFAULT '{}'::jsonb,
    scopes         text[] NOT NULL DEFAULT '{}',
    created_by     uuid REFERENCES users(id) ON DELETE SET NULL,
    last_checked_at timestamptz,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (org_id, connector_id, name)
);
CREATE INDEX connections_org_idx ON connections (org_id, created_at DESC);

CREATE TABLE agents (
    id              uuid PRIMARY KEY,
    org_id          uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    slug            text NOT NULL,
    name            text NOT NULL,
    description     text NOT NULL DEFAULT '',
    status          text NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'active', 'paused', 'archived')),
    current_version integer NOT NULL DEFAULT 0,
    labels          jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by      uuid REFERENCES users(id) ON DELETE SET NULL,
    archived_at     timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (org_id, slug)
);
CREATE INDEX agents_org_status_idx ON agents (org_id, status, created_at DESC);

CREATE TABLE agent_versions (
    id         uuid PRIMARY KEY,
    org_id     uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    agent_id   uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
    version    integer NOT NULL,
    spec       jsonb NOT NULL,
    definition_yaml text NOT NULL DEFAULT '',
    checksum   text NOT NULL,
    created_by uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (agent_id, version),
    UNIQUE (agent_id, checksum)
);
CREATE INDEX agent_versions_agent_idx ON agent_versions (agent_id, version DESC);

CREATE TABLE agent_instances (
    id               uuid PRIMARY KEY,
    org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    agent_id         uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
    agent_version_id uuid NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT,
    runtime_id       uuid NOT NULL REFERENCES runtimes(id) ON DELETE RESTRICT,
    name             text NOT NULL,
    deployment_target text NOT NULL DEFAULT 'local'
                     CHECK (deployment_target IN ('local', 'docker', 'kubernetes')),
    runtime_ref      text,
    state            text NOT NULL DEFAULT 'pending'
                     CHECK (state IN ('pending', 'starting', 'running', 'stopping', 'stopped', 'failed')),
    health           jsonb NOT NULL DEFAULT '{}'::jsonb,
    config           jsonb NOT NULL DEFAULT '{}'::jsonb,
    last_heartbeat_at timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX agent_instances_agent_idx ON agent_instances (agent_id, created_at DESC);

CREATE TABLE triggers (
    id                 uuid PRIMARY KEY,
    org_id             uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    agent_id           uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
    kind               text NOT NULL
                       CHECK (kind IN ('schedule', 'webhook', 'event', 'manual')),
    enabled            boolean NOT NULL DEFAULT true,
    config             jsonb NOT NULL DEFAULT '{}'::jsonb,
    webhook_token_hash text,
    last_fired_at      timestamptz,
    next_run_at        timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX triggers_agent_idx ON triggers (agent_id, created_at DESC);
CREATE INDEX triggers_next_run_idx ON triggers (next_run_at) WHERE enabled AND kind = 'schedule';
CREATE UNIQUE INDEX triggers_webhook_token_idx ON triggers (webhook_token_hash)
    WHERE webhook_token_hash IS NOT NULL;

CREATE TABLE executions (
    id               uuid PRIMARY KEY,
    org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    agent_id         uuid NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
    agent_version_id uuid NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT,
    agent_name       text NOT NULL,
    runtime_kind     text NOT NULL,
    trigger_id       uuid REFERENCES triggers(id) ON DELETE SET NULL,
    trigger_source   text NOT NULL DEFAULT 'manual'
                     CHECK (trigger_source IN ('manual', 'schedule', 'webhook', 'connector_event', 'agent_event', 'api')),
    status           text NOT NULL DEFAULT 'queued'
                     CHECK (status IN ('queued', 'dispatched', 'running', 'awaiting_approval',
                                       'succeeded', 'failed', 'timed_out', 'cancelled', 'rejected')),
    session_ref      text,
    input            jsonb NOT NULL DEFAULT '{}'::jsonb,
    output           jsonb,
    error            jsonb,
    usage            jsonb NOT NULL DEFAULT '{}'::jsonb,
    timeout_seconds  integer NOT NULL DEFAULT 300 CHECK (timeout_seconds BETWEEN 1 AND 86400),
    idempotency_key  text UNIQUE,
    cancel_requested boolean NOT NULL DEFAULT false,
    requested_by     uuid REFERENCES users(id) ON DELETE SET NULL,
    worker_id        text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    started_at       timestamptz,
    finished_at      timestamptz,
    updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX executions_org_created_idx ON executions (org_id, created_at DESC, id DESC);
CREATE INDEX executions_agent_created_idx ON executions (agent_id, created_at DESC, id DESC);
CREATE INDEX executions_pending_idx ON executions (created_at)
    WHERE status IN ('queued', 'dispatched', 'running');
CREATE INDEX executions_status_idx ON executions (org_id, status);

CREATE TABLE execution_events (
    id           bigserial PRIMARY KEY,
    org_id       uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    execution_id uuid NOT NULL REFERENCES executions(id) ON DELETE CASCADE,
    seq          bigint NOT NULL,
    kind         text NOT NULL
                 CHECK (kind IN ('status', 'log', 'tool_call', 'output', 'error', 'metric')),
    level        text NOT NULL DEFAULT 'info'
                 CHECK (level IN ('debug', 'info', 'warn', 'error')),
    message      text NOT NULL,
    data         jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (execution_id, seq)
);
CREATE INDEX execution_events_execution_idx ON execution_events (execution_id, seq);

CREATE TABLE approvals (
    id               uuid PRIMARY KEY,
    org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    execution_id     uuid NOT NULL REFERENCES executions(id) ON DELETE CASCADE,
    status           text NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending', 'approved', 'rejected', 'expired')),
    requested_action jsonb NOT NULL DEFAULT '{}'::jsonb,
    decided_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    decided_at       timestamptz,
    comment          text,
    expires_at       timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX approvals_pending_idx ON approvals (org_id, status, created_at DESC);

CREATE TABLE policies (
    id         uuid PRIMARY KEY,
    org_id     uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name       text NOT NULL,
    scope      text NOT NULL DEFAULT 'organization'
               CHECK (scope IN ('organization', 'agent', 'connection')),
    scope_id   uuid,
    document   jsonb NOT NULL DEFAULT '{}'::jsonb,
    enabled    boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (org_id, name)
);

CREATE TABLE audit_logs (
    id          bigserial PRIMARY KEY,
    org_id      uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    actor_type  text NOT NULL DEFAULT 'user'
                CHECK (actor_type IN ('user', 'api_token', 'system', 'worker')),
    actor_id    uuid,
    actor_email text,
    action      text NOT NULL,
    target_type text,
    target_id   uuid,
    metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
    request_id  text,
    ip_address  text,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_org_time_idx ON audit_logs (org_id, created_at DESC);

CREATE TABLE processed_events (
    event_id     uuid PRIMARY KEY,
    subject      text NOT NULL,
    consumer     text NOT NULL DEFAULT 'orbit-worker',
    received_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE secrets (
    reference   text PRIMARY KEY,
    org_id      uuid REFERENCES organizations(id) ON DELETE CASCADE,
    ciphertext  text NOT NULL,
    description text NOT NULL DEFAULT '',
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);
